window.FenceExport = (() => {
  function downloadTextFile(filename, contents) {
    const blob = new Blob([contents], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    link.click();
    URL.revokeObjectURL(url);
  }

  function downloadEstimateCsv(estimate) {
    const rows = [
      ['Category', 'Amount'],
      ['Materials', estimate.materialCost],
      ['Labour', estimate.laborCost],
      ['Equipment', estimate.equipmentCost],
      ['Permits', estimate.permitCost],
      ['Utilities', estimate.utilityCost],
      ['Subtotal', estimate.subtotal],
      ['Tax', estimate.tax],
      ['Contingency', estimate.contingency],
      ['Total', estimate.total]
    ];
    const csv = rows.map((row) => row.join(',')).join('\n');
    downloadTextFile('estimate-export.csv', csv);
  }

  function downloadCatalogSnapshot(items = window.FenceSeedCatalog || []) {
    const csv = ['SKU,Name,Category,Unit,Price']
      .concat(items.map((item) => [item.sku, item.name, item.category, item.unit, item.price].join(',')))
      .join('\n');
    downloadTextFile('catalog-snapshot.csv', csv);
  }

  return {
    downloadTextFile,
    downloadEstimateCsv,
    downloadCatalogSnapshot
  };
})();
